        x=json.loads(p.read_text());m=x['measurements'];spec=next(c for c in config['cases'] if c['id']==p.parent.name);sources=m['unique_selected_sources'];info=m['native_information_candidates'];truth=x['metadata']['truth'];useful=len(info)==1 and info[0]['observed_report']==truth
        rows.append({'case':p.parent.name,'kind':spec['kind'],'roles':x['metadata']['roles'],'truth':truth,'selection':sources,'native_policy_candidates':[(r['branch'],r['policy']) for r in m['native_policy_candidates']],'native_action_candidates':[(r['branch'],r['selected_source']) for r in m['native_action_candidates']],'received_information':[(r['source'],r['observed_report']) for r in info],'unique_faithful_report_observed':useful,'resources':x['metadata']['resources'],'actual_receipts':x['receipts'],'interventions':x['interventions'],'P_fixed_source_report':x['metadata']['P_report'],'Q_fixed_source_report':x['metadata']['Q_report'],'primary_path':p.relative_to(root).as_posix()})
