    assert summary['source_hashes']['src/core/revisable_selection.py']==config['frozen_core_sha256'];(folder/'RESULTADOS.json').write_text(json.dumps(summary,indent=2),encoding='utf-8');print(json.dumps({'cases':len(rows),'baselines':baselines,'results':[(r['case'],r['selection'],r['received_information']) for r in rows]},ensure_ascii=True))
